D = carregar_enem("enem-2026-dia1-azul")
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def legendas(q):
    """A legenda de obra que fica entre a figura e a referência vai para a referência (ex.: 'PORTINARI, C. Futebol. Óleo...')."""
    par = [list(x) for x in q["paragrafos"]]; out = []
    for i, (t, x) in enumerate(par):
        if t == "p" and out and (out[-1][0] == "fig" or out[-1][0] == "leg") and i + 1 < len(par) and par[i + 1][0] in ("fonte", "p"):
            out.append(["leg", x]); continue
        if t == "fonte" and out and out[-1][0] == "leg":
            legs = []
            while out and out[-1][0] == "leg": legs.insert(0, out.pop()[1])
            out.append(["fonte", " ".join(legs) + " " + x]); continue
        out.append([t, x])
    out = [["p", x] if t == "leg" else [t, x] for t, x in out]
    return dict(q, paragrafos=out)


def E(n, trocas=()):
    h = enunciado_enem(legendas(D[n]))
    for a, b in trocas:
        if a not in h: print(f"[troca não aplicada] Q{n}: {a[:60]!r}\n   enunciado: {h[:300]!r}"); continue
        h = h.replace(a, b)
    return h


def poema(n, arq, alt):
    """Poema ou letra como imagem (a imagem já traz a referência): [[fig:1]] e o comando."""
    cmd = [x for t, x in paragrafos_enem(D[n]) if t == "p"][-1]
    return {"enunciado": "[[fig:1]]" + p(cmd), "imagens": figs((arq, alt))}


def Q_(n, materia, assunto, expl, tags=(), trocas=(), extra=None, alts=None, imagens=()):
    q = {"materia": materia, "assunto": assunto, "area": "Linguagens", "tags": list(tags), "numeroOriginal": int(str(n).split("-")[0]),
         "enunciado": E(n, trocas), "alternativas": dict(alts or D[n]["alternativas"]), "imagens": list(imagens), "explicacao": expl}
    if extra: q.update(extra)
    q["enunciado"] = SEM_LINHA(q["enunciado"])
    q["alternativas"] = {k: SEM_LINHA(v) for k, v in q["alternativas"].items()}
    return q


